import{_ as e,o as d,c as r,a2 as i}from"./chunks/framework.DnrXFDHb.js";const h=JSON.parse('{"title":"infrastructure/input — 输入适配器总览","description":"四种 InputSource 实现的比较与设计约定","frontmatter":{"title":"infrastructure/input — 输入适配器总览","description":"四种 InputSource 实现的比较与设计约定"},"headers":[],"relativePath":"architecture/infrastructure/input/overview.md","filePath":"architecture/infrastructure/input/overview.md","lastUpdated":1773326634000}'),o={name:"architecture/infrastructure/input/overview.md"};function a(c,t,n,u,s,l){return d(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="infrastructure-input-—-输入适配器总览" tabindex="-1">infrastructure/input — 输入适配器总览 <a class="header-anchor" href="#infrastructure-input-—-输入适配器总览" aria-label="Permalink to &quot;infrastructure/input — 输入适配器总览&quot;">​</a></h1><p><strong>源文件</strong>：<code>src/streammuse/infrastructure/input/</code></p><p>所有输入适配器均实现 <code>InputSource</code> 协议（见 <a href="./../../domain/interfaces.html">domain/interfaces</a>），提供 <code>read_events()</code> 迭代器和 <code>close()</code> 方法。</p><hr><h2 id="共同设计约定" tabindex="-1">共同设计约定 <a class="header-anchor" href="#共同设计约定" aria-label="Permalink to &quot;共同设计约定&quot;">​</a></h2><p><strong><code>tick=0</code> 约定</strong>：所有适配器发出的 <code>MusicalEvent</code> 中 <code>tick</code> 均设为 <code>0</code>，由 Application 层（<code>RealTimeMusicService._input_worker</code>）根据 <code>tempo.seconds_to_tick(elapsed)</code> 重新赋值实际 tick 值。</p><p>这一分离使适配器只管&quot;读取和发出事件&quot;，而不管&quot;时间&quot;，测试时也无需模拟时钟。</p><hr><h2 id="四种实现对比" tabindex="-1">四种实现对比 <a class="header-anchor" href="#四种实现对比" aria-label="Permalink to &quot;四种实现对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类</th><th>输入源</th><th>使用场景</th><th>依赖</th></tr></thead><tbody><tr><td><code>KeyboardInput</code></td><td>计算机键盘</td><td>开发调试、无 MIDI 硬件时演示</td><td><code>pynput</code></td></tr><tr><td><code>MidiDeviceInput</code></td><td>实体 MIDI 设备</td><td>生产环境，键盘演奏者</td><td><code>mido</code></td></tr><tr><td><code>MidiFileInput</code></td><td><code>.mid</code> 文件（实时模拟）</td><td>基准测试、MIDI 文件回放</td><td><code>mido</code></td></tr><tr><td><code>ListInput</code></td><td>Python <code>list</code></td><td>单元测试、预录序列回放</td><td>无</td></tr></tbody></table><hr><h2 id="详细文档" tabindex="-1">详细文档 <a class="header-anchor" href="#详细文档" aria-label="Permalink to &quot;详细文档&quot;">​</a></h2><ul><li><a href="./keyboard.html">keyboard.md</a> — <code>KeyboardInput</code>：键盘映射与 pynput 集成</li><li><a href="./midi_device.html">midi_device.md</a> — <code>MidiDeviceInput</code>：MIDI 硬件输入</li><li><a href="./midi_file.html">midi_file.md</a> — <code>MidiFileInput</code>：MIDI 文件实时模拟</li><li><a href="./list_input.html">list_input.md</a> — <code>ListInput</code>：测试用内存事件列表</li></ul>',13)])])}const m=e(o,[["render",a]]);export{h as __pageData,m as default};
